/* Text built from parts (labels with numbers and names). */
export const frPatterns: [RegExp, (m: RegExpMatchArray) => string][] = [
  [/^Exhibit (\d+): (.+)$/, (m) => `Œuvre ${m[1]} : ${m[2]}`],
  [/^Commission ([A-Z]): (.+)$/, (m) => `Commande ${m[1]} : ${fr[m[2]] ?? m[2]}`],
  [/^Room (\d+)$/, (m) => `Salle ${m[1]}`],
  [/^Room (\d+) · (.+)$/, (m) => `Salle ${m[1]} · ${fr[m[2]] ?? m[2]}`],
  [/^Exhibit (\d+)$/, (m) => `Œuvre ${m[1]}`],
  [/^Commission ([A-Z])$/, (m) => `Commande ${m[1]}`],
  [/^Stop (\d+) of (\d+)$/, (m) => `Étape ${m[1]} sur ${m[2]}`],
];
